// Generated by `npm run wasm:build`; Vite resolves the pinned package alias.
// @ts-expect-error generated WASM package is intentionally not committed
import initWasm, { analyze_image as analyzeImageWasm } from '@color-core-wasm';
import {
  parseWorkerRequest,
  type SerializedComputeError,
  type WorkerReply,
} from './worker-protocol';

let wasmReady: Promise<unknown> | null = null;

function initializeWasm() {
  wasmReady ??= initWasm();
  return wasmReady;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function errorReply(
  requestId: string,
  code: SerializedComputeError['code'],
  error: unknown
): WorkerReply {
  return {
    type: 'error',
    requestId,
    error: { code, message: errorMessage(error) || code },
  };
}

export async function handleWorkerRequest(
  value: unknown
): Promise<WorkerReply> {
  const candidateId =
    value &&
    typeof value === 'object' &&
    typeof (value as { requestId?: unknown }).requestId === 'string'
      ? (value as { requestId: string }).requestId
      : 'invalid-request';

  let request;
  try {
    request = parseWorkerRequest(value);
  } catch (error) {
    return errorReply(candidateId, 'invalid-request', error);
  }

  try {
    await initializeWasm();
  } catch (error) {
    return errorReply(request.requestId, 'wasm-init-failed', error);
  }

  try {
    const startedAt = performance.now();
    const rawResult = analyzeImageWasm(
      new Uint8Array(request.encodedBytes),
      request.params
    );
    const durationMs = performance.now() - startedAt;
    if (!rawResult || typeof rawResult !== 'object') {
      throw new Error('WASM analysis returned a non-object response');
    }
    return {
      type: 'result',
      requestId: request.requestId,
      result: { ...rawResult, durationMs },
    };
  } catch (error) {
    return errorReply(request.requestId, 'analysis-failed', error);
  }
}

if (typeof self !== 'undefined') {
  self.addEventListener('message', (event: MessageEvent<unknown>) => {
    void handleWorkerRequest(event.data).then((reply) =>
      self.postMessage(reply)
    );
  });
}
